python -c "import sys; sys.path.insert(0,'.'); import config,duckdb,os; db=config.DUCKDB_PATH; print('DuckDB ada?', os.path.exists(db)); con=duckdb.connect(db,read_only=True); tbls=[r[0] for r in con.execute('SHOW TABLES').fetchall()]; print('Tabel:', tbls); n=con.execute('SELECT COUNT(*) FROM transaksi').fetchone()[0]; print('Jumlah transaksi:', f'{n:,}'); p=con.execute('SELECT COUNT(*) FROM pola').fetchone()[0]; print('Jumlah pola:', p); cols=[d[0] for d in con.execute('SELECT * FROM cube LIMIT 0').description]; need=['cluster_kmeans','anomaly_type','transaction_type','jenis_tujuan','flag_IQR']; print('Kolom hilang:', [c for c in need if c not in cols]); jt=con.execute('SELECT jenis_tujuan, SUM(n) FROM cube GROUP BY jenis_tujuan').fetchall(); print('jenis_tujuan:', jt); proj='projection' in tbls; print('Proyeksi scatter aktif?', proj)"
